<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('administrator');
$search=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$where=[];$params=[];
if($search!==''){$where[]='(p.title LIKE ? OR p.reference_no LIKE ? OR st.matric_number LIKE ? OR v.original_filename LIKE ?)';$term='%'.$search.'%';array_push($params,$term,$term,$term,$term);}
$allowedTypes=['proposal','chapter_1','chapter_2','chapter_3','chapter_4','chapter_5','final_project','supporting_document'];if(in_array($type,$allowedTypes,true)){$where[]='s.document_type=?';$params[]=$type;}
$q=db()->prepare('SELECT s.id submission_id,s.document_type,s.status,s.submitted_at,p.id project_id,p.reference_no,p.title,d.name department,st.matric_number,st.first_name,st.last_name,v.id version_id,v.version_number,v.original_filename,v.file_size_bytes,v.uploaded_at,(SELECT sr.decision FROM submission_reviews sr JOIN submission_versions sv2 ON sv2.id=sr.submission_version_id WHERE sv2.submission_id=s.id ORDER BY sr.reviewed_at DESC LIMIT 1) latest_decision FROM submissions s JOIN projects p ON p.id=s.project_id JOIN departments d ON d.id=p.department_id JOIN users st ON st.id=s.student_id JOIN submission_versions v ON v.submission_id=s.id AND v.version_number=s.current_version'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY v.uploaded_at DESC LIMIT 500');$q->execute($params);$rows=$q->fetchAll();
$pageTitle='Submission Management';$crumbTrail=['Admin','Submissions'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="card filter-bar mb-3"><form method="get" class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input class="form-control" id="q" name="q" value="<?= e($search) ?>" placeholder="Search project, student or filename..." aria-label="Search submissions"></label><div class="filter-selects"><select class="form-select" id="type" name="type" aria-label="Document type" data-autosubmit><option value="">All Types</option><?php foreach($allowedTypes as $t): ?><option value="<?= e($t) ?>" <?= $type===$t?'selected':'' ?>><?= e(ui_doc_label($t)) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary btn-sm">Filter</button><?php if($search!==''||$type!==''): ?><a class="btn btn-outline-primary btn-sm" href="<?= e(url('admin/submissions.php')) ?>">Clear</a><?php endif; ?></form></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Submission Records</h2><span class="text-muted small"><?= count($rows) ?> latest versions</span></div><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Student</th><th>Project</th><th>Document</th><th>Version</th><th>Submitted</th><th>Status</th><th>Review</th><th class="text-end">File</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= e(trim(($r['first_name']??'').' '.($r['last_name']??''))?:$r['matric_number']) ?></strong><br><small class="text-muted"><?= e($r['matric_number']) ?></small></td><td><strong><?= e($r['reference_no']) ?></strong><br><?= e($r['title']) ?><br><small class="text-muted"><?= e($r['department']) ?></small></td><td><?= e(ui_doc_label($r['document_type'])) ?></td><td>v<?= (int)$r['version_number'] ?></td><td class="text-muted"><?= e(ui_date($r['uploaded_at'])) ?></td><td><?= ui_pill($r['status']) ?></td><td><?= e(ui_label($r['latest_decision']??'Pending')) ?></td><td class="text-end"><a class="view-link" href="<?= e(url('download.php?version='.(int)$r['version_id'])) ?>">Download</a></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="8"><div class="empty-state">No submissions match this filter.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
